package com.nthexperience.desktop;
import android.app.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.os.*;import android.provider.DocumentsContract;import android.util.LruCache;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Saved SAF photo albums with bounded real thumbnails; opening a picture reuses the retained viewer. */
final class EightPhotoLibrary extends LinearLayout {
    static final int PICK=8607;interface Host{void open(Uri uri,String name,String mime,String page);void pickPicture();}
    final Activity activity;final DesktopStore store;final Host host;final FrameLayout body;final TextView status;final Handler main=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();final ThreadPoolExecutor thumbs=new ThreadPoolExecutor(2,2,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(32),new ThreadPoolExecutor.DiscardPolicy());final LruCache<String,Bitmap> cache=new LruCache<String,Bitmap>(6*1024*1024){protected int sizeOf(String k,Bitmap b){return b.getAllocationByteCount();}};String page="";int generation;boolean closed;CancellationSignal cancel=new CancellationSignal();
    EightPhotoLibrary(Activity a,DesktopStore s,Host host){super(a);activity=a;store=s;this.host=host;setOrientation(VERTICAL);setBackgroundColor(0xfffafafa);setContentDescription("Photo album library");TenAppearance.preserve(this);EightAppUi.bar(a,this,"Photos",0xffa12a75);LinearLayout commands=EightAppUi.commands(a,this);commands.addView(EightAppUi.button(a,"All albums",()->show("")));commands.addView(EightAppUi.button(a,"Add photo folder",this::pick));commands.addView(EightAppUi.button(a,"Open picture",host::pickPicture));commands.addView(EightAppUi.button(a,"Up",this::back));status=EightAppUi.text(a,"",13);status.setPadding(Aero.dp(a,12),Aero.dp(a,7),Aero.dp(a,12),Aero.dp(a,7));addView(status);body=new FrameLayout(a);addView(body,new LayoutParams(-1,0,1));show("");}
    void pick(){try{activity.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),PICK);}catch(RuntimeException e){EightAppUi.error(activity,e);}}
    void result(Intent data){if(data==null||data.getData()==null)return;Uri tree=data.getData();try{activity.getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException e){EightAppUi.error(activity,e);return;}worker.execute(()->{try{String name=DocumentFolders.rootName(activity,tree);JSONObject row=EightPimModels.create();JSONArray albums=EightPimStore.rows(store,EightPimModels.ALBUMS);for(int i=0;i<albums.length();i++)if(tree.toString().equals(albums.optJSONObject(i).optString("uri")))row=albums.optJSONObject(i);row.put("name",name).put("uri",tree.toString());EightPimStore.save(store,EightPimModels.ALBUMS,row);main.post(()->{if(!closed)show(DocumentFolders.rootPage(tree.toString(),name));});}catch(Exception e){main.post(()->{if(!closed)EightAppUi.error(activity,e);});}});}
    void show(String next){if(closed)return;page=next;int request=++generation;cancel.cancel();cancel=new CancellationSignal();CancellationSignal signal=cancel;thumbs.getQueue().clear();body.removeAllViews();if(page.isEmpty()){JSONArray albums=EightPimStore.rows(store,EightPimModels.ALBUMS);List<String> labels=new ArrayList<>();for(int i=0;i<albums.length();i++)labels.add(albums.optJSONObject(i).optString("name"));status.setText(labels.isEmpty()?"Add a photo folder to create an album. Access stays with folders you choose.":labels.size()+" saved albums · Hold an album to forget its link");ListView list=EightAppUi.list(activity,labels,n->{JSONObject album=albums.optJSONObject(n);show(DocumentFolders.rootPage(album.optString("uri"),album.optString("name")));});list.setContentDescription("Photo albums");list.setOnItemLongClickListener((p,v,n,id)->{JSONObject row=albums.optJSONObject(n);Aero.dialog(activity).setTitle("Forget this album link?").setMessage("The pictures and folder are kept.").setNegativeButton("Cancel",null).setPositiveButton("Forget",(d,x)->{try{EightPimStore.delete(store,EightPimModels.ALBUMS,row.optString("id"));show("");}catch(JSONException e){EightAppUi.error(activity,e);}}).show();return true;});body.addView(list);return;}status.setText("Loading album…");String target=page;worker.execute(()->{try{DocumentFolders.Listing listing=DocumentFolders.read(activity,target,signal);List<DocumentFolders.Item> items=new ArrayList<>();for(DocumentFolders.Item item:listing.items)if(item.directory()||PhotoImage.picture(item.name,item.mime))items.add(item);main.post(()->{if(closed||request!=generation)return;status.setText(items.size()+" folders/pictures"+(listing.limited?" · Listing limited; choose a smaller folder":""));grid(items,target,request,signal);});}catch(Exception e){main.post(()->{if(closed||request!=generation)return;status.setText("Album access is unavailable. Add the folder again to reconnect it.");body.removeAllViews();body.addView(EightAppUi.button(activity,"Reconnect photo folder",this::pick));});}});}
    void grid(List<DocumentFolders.Item> items,String source,int request,CancellationSignal signal){body.removeAllViews();GridView grid=new GridView(activity);grid.setContentDescription("Album picture thumbnails");grid.setNumColumns(GridView.AUTO_FIT);grid.setColumnWidth(Aero.dp(activity,132));grid.setStretchMode(GridView.STRETCH_COLUMN_WIDTH);grid.setAdapter(new BaseAdapter(){public int getCount(){return items.size();}public Object getItem(int at){return items.get(at);}public long getItemId(int at){return at;}public View getView(int at,View old,ViewGroup parent){DocumentFolders.Item item=items.get(at);LinearLayout tile=Aero.column(activity);tile.setPadding(Aero.dp(activity,7),Aero.dp(activity,7),Aero.dp(activity,7),Aero.dp(activity,7));FrameLayout frame=new FrameLayout(activity);frame.setBackgroundColor(0xffe6e7eb);tile.addView(frame,new LayoutParams(-1,Aero.dp(activity,110)));frame.addView(new AeroIcon(activity,item.directory()?"files":"pictures"),new FrameLayout.LayoutParams(Aero.dp(activity,48),Aero.dp(activity,48),Gravity.CENTER));TextView title=EightAppUi.text(activity,item.name,13);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);tile.addView(title,new LayoutParams(-1,Aero.dp(activity,42)));tile.setContentDescription((item.directory()?"Photo folder ":"Photo thumbnail ")+item.name);if(!item.directory())try{Uri uri=DocumentFolders.documentUri(source,item.id);String key=uri.toString();ImageView image=new ImageView(activity);image.setScaleType(ImageView.ScaleType.CENTER_CROP);frame.addView(image,new FrameLayout.LayoutParams(-1,-1));Bitmap bitmap=cache.get(key);if(bitmap!=null)image.setImageBitmap(bitmap);else thumbs.execute(()->{if(closed||request!=generation||signal.isCanceled())return;try{PhotoImage photo=PhotoImage.read(activity,uri,signal,180,180L*180);if(closed||request!=generation){photo.bitmap.recycle();return;}cache.put(key,photo.bitmap);main.post(()->{if(!closed&&request==generation)image.setImageBitmap(photo.bitmap);});}catch(Exception|OutOfMemoryError ignored){}});}catch(JSONException ignored){}return tile;}});grid.setOnItemClickListener((p,v,n,id)->{DocumentFolders.Item item=items.get(n);try{if(item.directory())show(DocumentFolders.childPage(source,item));else host.open(DocumentFolders.documentUri(source,item.id),item.name,item.mime,source);}catch(JSONException e){EightAppUi.error(activity,e);}});body.addView(grid,new FrameLayout.LayoutParams(-1,-1));}
    boolean back(){if(page.isEmpty())return false;try{JSONObject path=DocumentFolders.path(page);JSONArray crumbs=path.getJSONArray("crumbs");if(crumbs.length()<=1)show("");else{crumbs.remove(crumbs.length()-1);show("folder:"+path);}return true;}catch(JSONException e){show("");return true;}}
    void close(){closed=true;generation++;cancel.cancel();worker.shutdownNow();thumbs.shutdownNow();main.removeCallbacksAndMessages(null);cache.evictAll();}
}
